package com.fuelflex.platform.operations.service;
import java.math.*; import java.time.OffsetDateTime; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.fuelflex.platform.common.exception.BusinessException; import com.fuelflex.platform.operations.entity.*; import com.fuelflex.platform.operations.repository.ShiftReconciliationRepository; import com.fuelflex.platform.sale.entity.SaleType; import com.fuelflex.platform.sale.repository.FuelSaleRepository; import lombok.RequiredArgsConstructor;
@Service @RequiredArgsConstructor @Transactional public class ShiftReconciliationService{
 private final ShiftReconciliationRepository reconciliations;private final FuelSaleRepository sales;
 public ShiftReconciliation calculate(PumpShiftAssignment shift){if(shift.getClosingIndex()==null||shift.getOpeningIndex()==null)throw new BusinessException("Les index de l’affectation sont requis pour le rapprochement.");BigDecimal metered=s(shift.getClosingIndex().subtract(shift.getOpeningIndex()));BigDecimal cash=s(sales.sumEffectiveQuantityByShiftAndType(shift.getId(),SaleType.CASH));BigDecimal credit=s(sales.sumEffectiveQuantityByShiftAndType(shift.getId(),SaleType.CREDIT));ShiftReconciliation r=reconciliations.findByShiftAssignmentId(shift.getId()).orElseGet(ShiftReconciliation::new);r.setShiftAssignment(shift);r.setOpeningIndex(s(shift.getOpeningIndex()));r.setClosingIndex(s(shift.getClosingIndex()));r.setMeteredVolume(metered);r.setCashVolume(cash);r.setCreditVolume(credit);r.setTotalSoldVolume(s(cash.add(credit)));r.setVolumeVariance(s(metered.subtract(cash).subtract(credit)));r.setCalculatedAt(OffsetDateTime.now());return reconciliations.save(r);}
 private BigDecimal s(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(3,RoundingMode.UNNECESSARY);}
}
